{
  "invariants": [
    {
      "invariant": "refus du mandatement en l'état",
      "statut": "respecte",
      "motif": "La réponse refuse explicitement : « n’engagez pas le mandatement des 800 € en l’état ».",
      "trace_lines": [105]
    },
    {
      "invariant": "bascule explicite de dirfi-fpt vers drh-fpt avant l'analyse indemnitaire",
      "statut": "respecte",
      "motif": "L’annonce « BASCULE vers drh-fpt pour le fond indemnitaire » précise que dirfi-fpt conserve le volet budgétaire et précède l’analyse indemnitaire.",
      "trace_lines": [50, 105]
    },
    {
      "invariant": "une délibération ne suffit pas à créer une gratification ad personam",
      "statut": "respecte",
      "motif": "La réponse indique : « Un vote du conseil ne suffirait donc pas à créer librement cette gratification ». Les textes consultés encadrent les régimes indemnitaires et prévoient des primes instituées par une disposition législative ou réglementaire.",
      "trace_lines": [84, 102, 105]
    },
    {
      "invariant": "aucun CIA, RIFSEEP ou ISFE présumé avant qualification de l'agent",
      "statut": "respecte",
      "motif": "La trace annonce que « le statut et le régime de l’agent restent inconnus ». La réponse conditionne la piste au cas où « l’agent relève du RIFSEEP » et exige le contrôle de son statut et de son cadre d’emplois, sans présumer d’ISFE.",
      "trace_lines": [50, 105]
    },
    {
      "invariant": "absence de régularisation rétroactive artificielle",
      "statut": "respecte",
      "motif": "La réponse écarte le vote ultérieur comme justification du mandatement présent et précise : « Cela ne valide […] ni une régularisation après coup ».",
      "trace_lines": [105]
    },
    {
      "invariant": "vérification des références sur une source officielle en vigueur",
      "statut": "non_verifiable",
      "motif": "Les articles du CGFP sont accompagnés de leur texte et de métadonnées de vigueur datées. Toutefois, la partie concernant la référence sénatoriale reste invérifiable : l’ouverture fournit « page_text_available:false » et aucun texte officiel, malgré l’affirmation de consultation dans la réponse.",
      "trace_lines": [77, 84, 102, 105]
    },
    {
      "invariant": "activation de la méthode recherche-juridique",
      "statut": "respecte",
      "motif": "L’annonce « J’applique les skills dirfi-fpt, drh-fpt et recherche-juridique » et l’attribution de la vérification des sources à recherche-juridique établissent l’activation. La lecture intégrale et sa séquence sont couvertes par l’attestation mécanique.",
      "trace_lines": [4, 50]
    },
    {
      "invariant": "absence d'indemnité de départ à la retraite instituée, établie sur une source officielle consultée (réponse ministérielle du 22/05/2025, question écrite n° 01222, senat.fr) ; CIA évoqué uniquement de façon conditionnelle, sans présumer le régime de l'agent",
      "statut": "non_verifiable",
      "motif": "La partie relative au CIA est respectée : « si l’agent relève du RIFSEEP » et « aucune éligibilité individuelle au CIA n’est établie ». La partie exigeant d’établir l’absence d’indemnité par la réponse ministérielle reste invérifiable : aucun contenu de cette page n’est présent à la ligne 77. La citation et l’affirmation de consultation de la réponse ne remplacent pas ce contenu officiel manquant.",
      "trace_lines": [77, 105]
    }
  ]
}

